breach.segment:
// Replicas only: instances that report replication thread states or lag
WHERE marker > 0 AND (io_thread IS NOT NULL OR sql_thread IS NOT NULL OR replica_lag_s IS NOT NULL)
// Breach: a thread is currently stopped (I/O No or Connecting, SQL No) or lag is negative, and that signal
// was broken in at least 3 observed minutes of the window (brief reconnects during primary restarts are ignored)
| WHERE (io_thread IN ("No", "Connecting") AND io_down_minutes >= 3)
     OR (sql_thread == "No" AND sql_down_minutes >= 3)
     OR (replica_lag_s < 0 AND inactive_minutes >= 3)
| SORT database_id ASC
// Up to 1000 breaching instances per run (the ES|QL default row limit); raise it for larger fleets
| LIMIT 1000
| KEEP database_id, io_thread, sql_thread, replica_lag_s, last_io_errno, last_sql_errno, io_down_minutes, sql_down_minutes, inactive_minutes
